// 1. 짧게 살다 가는 객체 (Young Generation)
function createTemp() {
  const temp = { id: Math.random() };
  // 함수 끝나면 temp는 가비지(Garbage)가 됨
}

// 2. 오래 살아남는 객체 (Old Generation)
const cache = [];
function save(data) {
  cache.push(data); // 전역 변수에 붙어있어서 안 죽음
}

createTemp();
createTemp(); // Scavenger(청소부)가 슥 훑고 지나감

save({ type: 'important' }); // 몇 번의 청소를 버티면 승진(Promotion)함
